// ---------- helpers ----------
const todayStr = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`; };
const parse = (s) => (s && /^\d{4}-\d{2}-\d{2}$/.test(s) ? new Date(s + "T00:00:00") : null);
const fmt = (s) => { const d = parse(s); return d ? d.toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"}) : (s || "—"); };

function due(p) {
  if (!p.lastVisit) return { label: "Never seen", status: "never", days: null };
  const next = new Date(parse(p.lastVisit).getTime() + p.cadenceDays * DAY);
  const d = Math.round((next - new Date()) / DAY);
  if (d < 0) return { label: `${Math.abs(d)} days overdue`, status: "overdue", days: d };
  if (d <= 14) return { label: `Due in ${d} days`, status: "soon", days: d };
  return { label: `Due in ${d} days`, status: "ok", days: d };
}

// competitor workload: overlapping active jobs today = how loaded
function workload(c) {
  const now = new Date();
  const active = (c.jobs || []).filter((j) => {
    const s = parse(j.start), e = parse(j.end);
    if (s && e) return s <= now && e >= now;
    if (s && !e) return s <= now;
    if (!s && e) return e >= now;
    return false;
  });
  const upcomingGap = (() => {
    const ends = active.map((j) => parse(j.end)).filter(Boolean).sort((a,b)=>a-b);
    if (!ends.length) return null;
    return Math.round((ends[0] - now) / DAY); // days until first active job frees up
  })();
  let status = "unknown";
  if ((c.jobs || []).length === 0) status = "unknown";
  else if (active.length >= 2) status = "slammed";
  else if (active.length === 1) status = "moderate";
  else status = "light";
  return { active: active.length, status, freesInDays: upcomingGap };
}

