function CompetitorDetail({ c, onPatch }) {
  const [j, setJ] = useState({ name:"", customer:"", start:"", end:"", source:"" });
  const w = workload(c);
  const add = () => { if(!j.name.trim())return; onPatch({ jobs:[...(c.jobs||[]), {...j, id:Date.now()}] }); setJ({name:"",customer:"",start:"",end:"",source:""}); };
  const rm = (id) => onPatch({ jobs:(c.jobs||[]).filter(x=>x.id!==id) });
  return (
    <div style={{ marginTop:12 }}>
      <div className="card" style={{ padding:"12px 14px", marginBottom:14, borderLeft:`3px solid ${loadC[w.status]}` }}>
        <div style={{ fontSize:12, color:C.dim }}>Read on their crew right now</div>
        <div style={{ fontSize:17, fontWeight:800, color:loadC[w.status] }}>{loadLabel[w.status]}</div>
        <div style={{ fontSize:12.5, color:C.dim, marginTop:2 }}>
          {w.active} active job{w.active===1?"":"s"}{w.status==="slammed"&&w.freesInDays!=null?` · frees up in ~${w.freesInDays} days`:""}
        </div>
      </div>

      <div className="lbl">Jobs they're on</div>
      <div style={{ display:"grid", gap:8, marginBottom:12 }}>
        {(c.jobs||[]).map(job=>(
          <div key={job.id} style={{ background:C.bg, border:`1px solid ${C.lineSolid}`, borderRadius:8, padding:"9px 11px" }}>
            <div style={{ display:"flex", justifyContent:"space-between", gap:8 }}>
              <div style={{ fontWeight:700, fontSize:14 }}>{job.name}</div>
              <span onClick={()=>rm(job.id)} style={{ cursor:"pointer", color:C.dim, fontSize:12 }}>remove</span>
            </div>
            {job.customer && <div style={{ fontSize:12.5, color:C.dim }}>{job.customer}</div>}
            <div style={{ fontSize:12, color:C.caliche, marginTop:2 }}>{fmt(job.start)} → {fmt(job.end)}{job.source?` · ${job.source}`:""}</div>
          </div>
        ))}
        {(c.jobs||[]).length===0 && <div style={{ fontSize:13, color:C.dim }}>No jobs logged yet.</div>}
      </div>

      <div style={{ background:C.panel2, border:`1px solid ${C.lineSolid}`, borderRadius:10, padding:11, display:"grid", gap:7 }}>
        <input className="fld" placeholder="Job name / scope" value={j.name} onChange={e=>setJ({...j,name:e.target.value})} />
        <input className="fld" placeholder="Customer / GC" value={j.customer} onChange={e=>setJ({...j,customer:e.target.value})} />
        <div style={{ display:"flex", gap:7 }}>
          <div style={{ flex:1 }}><div className="lbl">Start</div><input className="fld" type="date" value={j.start} onChange={e=>setJ({...j,start:e.target.value})} /></div>
          <div style={{ flex:1 }}><div className="lbl">Done</div><input className="fld" type="date" value={j.end} onChange={e=>setJ({...j,end:e.target.value})} /></div>
        </div>
        <input className="fld" placeholder="Source (bid tab, award notice, field…)" value={j.source} onChange={e=>setJ({...j,source:e.target.value})} />
        <button className="btn" onClick={add}>+ Add job</button>
      </div>
    </div>
  );
}

function Contacts({ obj, onPatch }) {
  const [c, setC] = useState({ name:"", role:"", phone:"", email:"" });
  const add = () => { if(!c.name.trim())return; onPatch({ contacts:[...(obj.contacts||[]), {...c, id:Date.now()}] }); setC({name:"",role:"",phone:"",email:""}); };
  const rm = (id) => onPatch({ contacts:(obj.contacts||[]).filter(x=>x.id!==id) });
  return (
    <div style={{ marginTop:16 }}>
      <div className="lbl">Contacts</div>
      <div style={{ display:"grid", gap:8, marginBottom:10 }}>
        {(obj.contacts||[]).map(ct=>(
          <div key={ct.id} style={{ background:C.bg, border:`1px solid ${C.lineSolid}`, borderRadius:8, padding:"9px 11px" }}>
            <div style={{ display:"flex", justifyContent:"space-between" }}>
              <div style={{ fontWeight:700, fontSize:14 }}>{ct.name}</div>
              <span onClick={()=>rm(ct.id)} style={{ cursor:"pointer", color:C.dim, fontSize:12 }}>remove</span>
            </div>
            {ct.role && <div style={{ fontSize:12.5, color:C.dim }}>{ct.role}</div>}
            <div style={{ fontSize:13, marginTop:3 }}>
              {ct.phone && <a href={`tel:${ct.phone}`} style={{ marginRight:14 }}>{ct.phone}</a>}
              {ct.email && <a href={`mailto:${ct.email}`}>{ct.email}</a>}
            </div>
          </div>
        ))}
      </div>
      <div style={{ background:C.panel2, border:`1px solid ${C.lineSolid}`, borderRadius:10, padding:11, display:"grid", gap:7 }}>
        <input className="fld" placeholder="Name" value={c.name} onChange={e=>setC({...c,name:e.target.value})} />
        <input className="fld" placeholder="Position / title" value={c.role} onChange={e=>setC({...c,role:e.target.value})} />
        <div style={{ display:"flex", gap:7 }}>
          <input className="fld" placeholder="Mobile" value={c.phone} onChange={e=>setC({...c,phone:e.target.value})} />
          <input className="fld" placeholder="Email" value={c.email} onChange={e=>setC({...c,email:e.target.value})} />
        </div>
        <button className="btn" onClick={add}>+ Add contact</button>
      </div>
    </div>
  );
}

// ---------- small UI ----------
const mapUrl = (query) => `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
const MapPin = ({ query }) => query ? (
  <a href={mapUrl(query)} target="_blank" rel="noopener noreferrer"
     style={{ display:"inline-flex", alignItems:"center", gap:6, background:C.panel2, border:`1px solid ${C.lineSolid}`,
       borderRadius:8, padding:"9px 13px", fontSize:14, fontWeight:700, color:C.steel, textDecoration:"none" }}>
    <span style={{ fontSize:16 }}>📍</span> Open in Maps
  </a>
) : null;
const RegionPicker = ({ value, onChange }) => {
  const set = new Set(value && value.length ? value : ["unset"]);
  const toggle = (k) => {
    const s = new Set(set); s.delete("unset");
    if (s.has(k)) s.delete(k); else s.add(k);
    onChange(s.size ? [...s] : ["unset"]);
  };
  return (
    <div style={{ display:"flex", flexWrap:"wrap", gap:6 }}>
      {REGIONS.filter(r=>r.key!=="unset").map(r=>(
        <div key={r.key} onClick={()=>toggle(r.key)}
          style={{ cursor:"pointer", padding:"7px 12px", borderRadius:18, fontSize:12.5, fontWeight:700,
            background: set.has(r.key)?C.rust:C.panel2, color: set.has(r.key)?"#fff":C.dim,
            border:`1px solid ${set.has(r.key)?C.rust:C.lineSolid}` }}>
          {r.label}
        </div>
      ))}
    </div>
  );
};
const Splash = () => <div style={{ background:C.bg, minHeight:"100vh", display:"grid", placeItems:"center", gap:0 }}><div style={{ textAlign:"center" }}><img src={LOGO} alt="HARMAC Energy" style={{ height:70, width:"auto", marginBottom:16, opacity:.95 }} /><div style={{ color:C.dim, fontFamily:"monospace", fontSize:13, letterSpacing:".1em" }}>COMMAND CENTER</div></div></div>;

// ---------- PIN keypad shared by lock screen + admin gate ----------
function PinPad({ title, subtitle, onSubmit, error, pinLength = 4 }) {
  const [val, setVal] = useState("");
  const press = (d) => {
    if (val.length >= pinLength) return;
    const next = val + d;
    setVal(next);
    if (next.length === pinLength) {
      onSubmit(next);
      setVal("");
    }
  };
  const back = () => setVal(val.slice(0, -1));
  return (
    <div style={{ background:C.bg, minHeight:"100vh", display:"grid", placeItems:"center", padding:20 }}>
      <div style={{ textAlign:"center", width:"100%", maxWidth:320 }}>
        <img src={LOGO} alt="HARMAC Energy" style={{ height:52, width:"auto", marginBottom:22, opacity:.95 }} />
        <div style={{ color:C.text, fontSize:17, fontWeight:800, marginBottom:4 }}>{title}</div>
        {subtitle && <div style={{ color:C.dim, fontSize:13, marginBottom:18 }}>{subtitle}</div>}
        <div style={{ display:"flex", justifyContent:"center", gap:10, marginBottom:22 }}>
          {Array.from({length:pinLength}).map((_,i)=>(
            <div key={i} style={{ width:16, height:16, borderRadius:9, border:`2px solid ${C.lineSolid}`,
              background: i<val.length ? C.rust : "transparent", borderColor: i<val.length?C.rust:C.lineSolid }} />
          ))}
        </div>
        {error && <div style={{ color:C.red, fontSize:13, fontWeight:700, marginBottom:14 }}>{error}</div>}
        <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:10, marginBottom:16 }}>
          {["1","2","3","4","5","6","7","8","9"].map(d=>(
            <button key={d} className="btn" onClick={()=>press(d)} style={{ fontSize:20, padding:"16px 0" }}>{d}</button>
          ))}
          <div />
          <button className="btn" onClick={()=>press("0")} style={{ fontSize:20, padding:"16px 0" }}>0</button>
          <button className="btn" onClick={back} style={{ fontSize:14, padding:"16px 0" }}>⌫</button>
        </div>
      </div>
    </div>
  );
}

function LockScreen({ correctPin, onUnlock }) {
  const [error, setError] = useState("");
  const check = (val) => {
    if (val === correctPin) { setError(""); onUnlock(); }
    else setError("Wrong PIN — try again.");
  };
  return <PinPad title="Enter PIN" subtitle="HARMAC Command Center is locked" onSubmit={check} error={error} pinLength={(correctPin||"1234").length} />;
}

function AdminGate({ correctPin, onUnlock }) {
  const [error, setError] = useState("");
  const check = (val) => {
    if (val === correctPin) { setError(""); onUnlock(); }
    else setError("Wrong admin PIN.");
  };
  return (
    <div style={{ maxWidth:340, margin:"40px auto" }}>
      <PinPad title="Admin PIN" subtitle="Enter the admin PIN to manage settings" onSubmit={check} error={error} pinLength={(correctPin||"9999").length} />
    </div>
  );
}

function AdminPanel({ pins, onSavePins, onLockDevice }) {
  const [appPin, setAppPin] = useState(pins.appPin);
  const [adminPin, setAdminPin] = useState(pins.adminPin);
  const [saved, setSaved] = useState(false);

  const save = () => {
    const clean = (s) => (s || "").replace(/\D/g,"").slice(0,6);
    const a = clean(appPin), b = clean(adminPin);
    if (a.length < 4 || b.length < 4) { alert("PINs should be at least 4 digits."); return; }
    onSavePins({ appPin:a, adminPin:b });
    setAppPin(a); setAdminPin(b);
    setSaved(true);
    setTimeout(()=>setSaved(false), 2500);
  };

  return (
    <div>
      <H>Admin</H>
      <div style={{ fontSize:13, color:C.dim, marginBottom:20 }}>
        Manage the PINs that protect the app. The app PIN opens the Command Center;
        the admin PIN gets in here. Changes sync to every device.
      </div>

      <div className="card" style={{ padding:16, marginBottom:16 }}>
        <div className="lbl">App PIN (opens the Command Center)</div>
        <input className="fld" inputMode="numeric" maxLength={6} value={appPin}
          onChange={e=>setAppPin(e.target.value.replace(/\D/g,""))} style={{ marginBottom:12, letterSpacing:"0.3em", fontSize:18 }} />
        <div className="lbl">Admin PIN (opens this Admin tab)</div>
        <input className="fld" inputMode="numeric" maxLength={6} value={adminPin}
          onChange={e=>setAdminPin(e.target.value.replace(/\D/g,""))} style={{ letterSpacing:"0.3em", fontSize:18 }} />
      </div>

      <div style={{ display:"flex", gap:10, alignItems:"center", marginBottom:26 }}>
        <button className="btn p" onClick={save}>Save PINs</button>
        {saved && <span style={{ color:C.green, fontSize:13, fontWeight:700 }}>Saved ✓</span>}
      </div>

      <div className="card" style={{ padding:16, borderLeft:`3px solid ${C.amber}` }}>
        <div style={{ fontWeight:700, marginBottom:6 }}>Lock this device</div>
        <div style={{ fontSize:13, color:C.dim, marginBottom:12, lineHeight:1.5 }}>
          Forces this phone or computer to ask for the app PIN again next time it's opened.
          Use this if you're handing the device to someone else or want to re-secure it.
        </div>
        <button className="btn" onClick={onLockDevice}>Lock now</button>
      </div>

      <div style={{ fontSize:12, color:C.dim, marginTop:20, lineHeight:1.5, borderTop:`1px solid ${C.lineSolid}`, paddingTop:12 }}>
        Note: this PIN protects casual access to the app on a device. It is not full
        multi-user login security — anyone with your web link and a PIN can still see
        and edit everything. For real per-person accounts, that's a future build.
      </div>
    </div>
  );
}
const H = ({children}) => <div style={{ fontSize:22, fontWeight:800, marginBottom:16, letterSpacing:"-.02em" }}>{children}</div>;
const Sub = ({children,c}) => <div style={{ fontSize:12, textTransform:"uppercase", letterSpacing:".08em", color:c, fontWeight:800, marginBottom:10 }}>{children}</div>;
const Stat = ({n,label,c}) => <div className="card" style={{ padding:"15px 16px", borderTop:`3px solid ${c}` }}><div style={{ fontSize:32, fontWeight:800, color:c, lineHeight:1 }}>{n}</div><div style={{ fontSize:12.5, color:C.dim, marginTop:5 }}>{label}</div></div>;
const Tag = ({children,c}) => <span style={{ fontSize:10, color:c, border:`1px solid ${c}66`, borderRadius:5, padding:"1px 6px", fontWeight:700, letterSpacing:".04em" }}>{children}</span>;
const Pill = ({children,on,onClick}) => <div onClick={onClick} style={{ cursor:"pointer", padding:"8px 14px", borderRadius:20, fontSize:13.5, fontWeight:700, background:on?C.rust:C.panel2, color:on?"#fff":C.dim, border:`1px solid ${on?C.rust:C.lineSolid}` }}>{children}</div>;
const Empty = ({onAdd}) => <div style={{ color:C.dim, padding:24, textAlign:"center", border:`1px dashed ${C.lineSolid}`, borderRadius:12 }}>Nothing here yet. <span onClick={onAdd} style={{ color:C.rust, cursor:"pointer", fontWeight:700 }}>Add one.</span></div>;
const Intel = ({title,body,c}) => <div style={{ background:C.bg, border:`1px solid ${C.lineSolid}`, borderLeft:`3px solid ${c}`, borderRadius:8, padding:"9px 11px", marginTop:8 }}><div style={{ fontSize:10, textTransform:"uppercase", letterSpacing:".08em", color:c, fontWeight:800, marginBottom:3 }}>{title}</div><div style={{ fontSize:13.5, lineHeight:1.5 }}>{body}</div></div>;
const MsaTag = ({s}) => { const m={none:["No MSA",C.dim],requested:["MSA asked",C.amber],"in-review":["In review",C.steel],signed:["Signed",C.green]}; const [t,c]=m[s]||m.none; return <Tag c={c}>{t}</Tag>; };
const StatusTag = ({s}) => { const m={planned:["Planned",C.dim],"open-season":["Open season",C.steel],"under-bid":["Under bid",C.amber],awarded:["Awarded",C.green],"under-construction":["Building",C.steel],commissioned:["Done",C.dim]}; const [t,c]=m[s]||m.planned; return <Tag c={c}>{t}</Tag>; };
const VisitRow = ({p,onOpen,onLog}) => (
  <div className="card" style={{ padding:"12px 14px", display:"flex", alignItems:"center", gap:12, borderLeft:`3px solid ${stC[p.d.status]}` }}>
    <div style={{ flex:1, minWidth:0, cursor:"pointer" }} onClick={onOpen}>
      <div style={{ fontWeight:700 }}>{p.name}</div>
      <div style={{ fontSize:12.5, color:stC[p.d.status], fontWeight:600 }}>{p.d.label}</div>
    </div>
    <button className="btn" onClick={onLog}>Visited</button>
  </div>
);

